net correlated_join "Ship a ready order with its own account's settings and a courier for its region"

@order_in: (orders) -purchase-> [ship] -shipment-> (shipped)
@settings_in: (settings) -setting->? [ship]
@courier_in: (couriers) -courier-> [ship]
@not_paused: (pauses) -pause->0 [ship]
[ship] -courier-> (couriers)
[ship] handler "ship_order"

@order_in predicate cel "status == 'ready'"
@settings_in correlate cel "token.account == binding.orders[0].account"
@courier_in predicate cel "available"
@courier_in correlate cel "token.region == binding.orders[0].region"
@not_paused correlate cel "token.account == binding.orders[0].account"

marking initial (orders) <- $order_a
marking initial (orders) <- $order_b
marking initial (settings) <- $settings_a
marking initial (settings) <- $settings_b
marking initial (couriers) <- $courier_east
marking initial (couriers) <- $courier_west

$order_a: purchase {"account": "A", "region": "west", "status": "ready"}
$order_b: purchase {"account": "B", "region": "east", "status": "ready"}
$settings_a: setting {"account": "A", "carrier": "post"}
$settings_b: setting {"account": "B", "carrier": "van"}
$courier_east: courier {"available": true, "region": "east"}
$courier_west: courier {"available": true, "region": "west"}
